mapper.select:
select id, user_id, game_type, challenge_date, region_id, start_at, clear_at, source, created_at, updated_at
from user_daily_challenge
where user_id = #{userId}
  and game_type = #{gameType, jdbcType=INTEGER, typeHandler=com.sniper.game.wordgame.typehandler.GameTypeEnumTypeHandler}
  and challenge_date = #{challengeDate}
limit 1

mapper.update:
update user_daily_challenge
set start_at = #{startAt},
    clear_at = #{clearAt},
    updated_at = now()
where user_id = #{userId}
  and game_type = #{gameType, jdbcType=INTEGER, typeHandler=com.sniper.game.wordgame.typehandler.GameTypeEnumTypeHandler}
  and challenge_date = #{challengeDate}
  and (
        start_at is null
        or clear_at is null
        or timestampdiff(second, #{startAt}, #{clearAt}) < timestampdiff(second, start_at, clear_at)
      )

mapper.select:
select timestampdiff(second, start_at, clear_at)
from user_daily_challenge
where user_id = #{userId}
  and game_type = #{gameType, jdbcType=INTEGER, typeHandler=com.sniper.game.wordgame.typehandler.GameTypeEnumTypeHandler}
  and challenge_date = #{challengeDate}
  and start_at is not null
  and clear_at is not null
limit 1
